import {privacyConfig,privacyDestination} from './privacy-model.mjs';
import {DEFAULT_PRIVACY} from './privacy-defaults.mjs';
const e=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
export function renderPrivacyNotice(content){
 const p=privacyConfig(content),copy=value=>String(value).replaceAll(DEFAULT_PRIVACY.email,p.email);
 const body=text=>text.split(/\n\s*\n/).map(block=>block.trim().startsWith('- ')?'<ul>'+block.split('\n').map(line=>'<li>'+e(copy(line.replace(/^-\s*/,'')))+'</li>').join('')+'</ul>':'<p>'+e(copy(block)).replaceAll('\n','<br>')+'</p>').join('');
 return `<article class="privacy wrap"><header class="privacy-heading"><p class="privacy-eyebrow">${e(p.eyebrow)}</p><h1>${e(p.title)}</h1><p class="privacy-updated">Última actualización: ${e(new Intl.DateTimeFormat('es-MX',{dateStyle:'long',timeZone:'UTC'}).format(new Date(p.updated+'T12:00:00Z')))}.</p></header>${p.sections.map(s=>`<section class="privacy-section"><h2>${e(s.title)}</h2>${s.id==='responsible'?`<p>${e(p.responsibleName)}, quien opera bajo el nombre comercial ${e(p.brand)}, es responsable del tratamiento descrito en este aviso. Domicilio: ${e(p.address)}. Correo de contacto: <a href="mailto:${e(p.email)}">${e(p.email)}</a>.</p>`:''}${body(s.body)}${s.links.length?'<p>'+s.links.map(link=>`<a href="${e(privacyDestination(copy(link.href))||'#')}"${link.href.startsWith('https:')?' target="_blank" rel="noopener noreferrer"':''}>${e(copy(link.label))}</a>`).join(' · ')+'</p>':''}${s.id==='storage'?'<button class="button button-outline" type="button" data-clear-preferences>Borrar mis preferencias de este navegador</button><p role="status" aria-live="polite" data-privacy-status></p>':''}</section>`).join('')}<div class="privacy-contact"><p>${e(p.contactHeading)}</p><a class="text-link" href="mailto:${e(p.email)}">${e(p.contactButton)}</a></div></article>`;
}
